// Local conversations and finite village commissions; no rendering dependency.
export const VILLAGERS={
 anna:{id:'anna',name:'Anna',role:'Kräuterhändlerin',region:'village',x:-7,z:5,coat:'#677e63',hair:'#6a4837',skin:'#dbac89',intro:'Du kommst von der Portmann-Alp? Dann kennst du sicher diesen Duft nach Bergthymian. Willkommen im Dorf. Hier hilft man sich, bevor man grosse Pläne schmiedet.',returning:'Schön, bist du wieder da. Was erzählt die Alp heute?',finished:'Vom ersten Kräuterbund bis zum Gipfelbuch: Du hast das Dorf und die Berge miteinander verbunden. Die Wege bleiben für dich offen.',topics:{herbs:['Wo finde ich Kräuter?','Auf deiner Alp stehen sieben Bergthymianstellen. Pflücke behutsam. Nach einer Nacht in der Hütte gibt es neuen Nachschub. Für meine Lieferung brauche ich drei Portionen im Rucksack.'],cellar:['Was hat es mit dem Dorfhaus auf sich?','Im Dorfhaus führt eine Treppe in den Keller. Schau dir dort das alte Regal an. Der Hinweis verbindet Wasser, eine Blüte und den Berg. Ich würde ihn lesen, bevor ich an den Steinrädern drehe.']}},
 sepp:{id:'sepp',name:'Sepp',role:'Käser',region:'village',x:10,z:1,coat:'#c9b78d',hair:'#d2c3a8',skin:'#d5a17f',intro:'Grüezi! Für guten Käse braucht es gute Milch. Und für gute Milch braucht es Tiere, denen es gut geht. Wie geht es Berta und Lotti?',returning:'Die Käse ruhen. Wir müssen das nicht. Was liegt an?',finished:'Deine Milch ist angekommen. Wenn du wieder auf die Alp gehst: Grüss mir die beiden Kühe.',topics:{milk:['Wie bekomme ich Milch?','Futter, Wasser und Zuwendung für Berta und Lotti: Dann kannst du je zwei Portionen melken. Die tägliche Grundration liegt in der Futterscheune, den Eimer füllst du am Alpbrunnen.'],craft:['Was mache ich aus Milch?','In deiner Hüttenküche kannst du Milch zu Honigmilch, Alpbrei oder einer Kräuteromelette verarbeiten. Eier findest du nach der Versorgung bei den Hühnern. Das Rezeptbuch zeigt die genauen Zutaten.']}},
 ruth:{id:'ruth',name:'Ruth',role:'Wirtin',region:'village',x:19,z:14,coat:'#985e51',hair:'#413a34',skin:'#e2b394',intro:'Setz dich gedanklich schon einmal an den Stammtisch. Noch fehlt mir eine gute Mahlzeit für die Wandernden. Selber gekocht schmeckt besser als jede Ausrede.',returning:'Hungrige Gäste gibt es immer. Hast du etwas Feines mitgebracht?',finished:'Deine Kräuteromelette war genau richtig. Dani plant schon die nächste Berggeschichte.',topics:{meal:['Was gehört in die Omelette?','Zwei Eier, eine Milch und eine Portion Bergthymian. Koche die Omelette in der Alphütte und bring sie mir, solange sie noch in deinem Rucksack liegt.'],energy:['Wie plane ich die Verpflegung?','Raste vor dem Aufbruch. In der Hütte kostet das nichts. Ein Käsebrot gibt dir 45 Energie, eine Kräuteromelette bis zu 52. Für längere Wege lohnt sich selbst gemachter Tourenproviant.']}},
 dani:{id:'dani',name:'Dani',role:'Bergführer',region:'village',x:-7,z:14,coat:'#527c8a',hair:'#584b3c',skin:'#c99474',intro:'Ein Gipfel läuft dir nicht davon. Zuerst Versorgung, dann Wegzeichen und Ausrüstung. Ich gebe dir ein paar Aufträge, mit denen du die Bergwelt kennenlernst.',returning:'Wie waren die Wege? Erzähl lieber von einem sicheren Rückweg als von einer schnellen Zeit.',finished:'Du warst am Portmann-Gipfel und bist zurück. Das ist die Geschichte, die am Stammtisch zählt.',topics:{route:['Wie komme ich in die Berge?','Der alte Weg beginnt im Dorfhaus-Keller. Hinter der Steintür führt der Gang zum Arvenwald. Am Wald verzweigt er sich: über Alpenrosenhang und Sonnenalp oder über See, Schlucht und Kristallgrotte zum Grat.'],climb:['Muss ich klettern?','Die Wanderwege bleiben frei. Für meine Sicherheitsaufgabe übst du am Übungsfels deiner Alp. Die grösseren Kletterrouten verlangen zusätzlich Bergschuhe, Seil und Gurt. Schliesse zuerst die Übungsroute ab.']}}
};
