export const freshVillage=()=>({met:[],topics:[],accepted:[],completed:[]});
const fail=message=>({ok:false,message});
export function nearVillager(s,id){const n=VILLAGERS[id],p=s.position;return !!n&&p.region===n.region&&!p.inside&&!s.climbing?.checkpoint&&Math.hypot(p.x-n.x,p.z-n.z)<2.8;}
export function talk(s,id,topic=null){if(!nearVillager(s,id))return fail('Gehe zuerst zu dieser Person im Bergdorf.');const n=VILLAGERS[id];if(topic!==null&&!Object.hasOwn(n.topics,topic))return fail('Dieses Gesprächsthema gibt es nicht.');const known=s.village.met.includes(id);if(!known)s.village.met.push(id);if(topic!==null){const key=id+':'+topic;if(!s.village.topics.includes(key))s.village.topics.push(key);return{ok:true,message:n.topics[topic][1]};}return{ok:true,message:s.village.completed.includes('village-home')?n.finished:known?n.returning:n.intro};}
export function orderStatus(s,id){const o=ORDERS.find(o=>o.id===id);if(!o)return{phase:'unknown',missing:[]};if(s.village.completed.includes(id))return{phase:'completed',missing:[]};if(!o.requires.every(k=>s.village.completed.includes(k)))return{phase:'locked',missing:[]};if(!s.village.accepted.includes(id))return{phase:'available',missing:[]};const missing=[];for(const[k,n]of Object.entries(o.take))if((s.inventory[k]||0)<n)missing.push({item:k,amount:n-(s.inventory[k]||0)});for(const k of o.discoveries||[])if(!s.adventure.discoveries.includes(k))missing.push({discovery:k});if(o.climb&&!s.climbing.completed.includes(o.climb))missing.push({climb:o.climb});return{phase:missing.length?'active':'ready',missing};}
export function acceptOrder(s,id,npc){const o=ORDERS.find(o=>o.id===id);if(!o||o.npc!==npc||!nearVillager(s,npc)||!s.village.met.includes(npc))return fail('Sprich zuerst mit der Auftragsperson vor Ort.');if(orderStatus(s,id).phase!=='available')return fail('Dieser Auftrag kann jetzt nicht angenommen werden.');s.village.accepted.push(id);return{ok:true,message:'Auftrag angenommen: '+o.name+'. Du findest ihn im Aufgabenbuch.'};}
export function finishOrder(s,id,npc,exchange){const o=ORDERS.find(o=>o.id===id);if(!o||o.npc!==npc||!nearVillager(s,npc))return fail('Kehre zur richtigen Auftragsperson im Bergdorf zurück.');if(orderStatus(s,id).phase!=='ready')return fail('Der Auftrag ist noch offen oder wurde bereits abgeschlossen.');const result=exchange(s,{take:o.take,earn:o.reward,stats:{earned:o.reward},reason:'order',ref:id});if(!result.ok)return result;s.village.completed.push(id);return{ok:true,message:o.reply};}
